/* Isolated v3 persistence. Legacy stores are read/export-only. No network calls. */
import {validate} from './engine.mjs';
import {sha256Text,randomSessionId} from './crypto-compat.mjs';
const NAME='ashen-covenant-v3',KEY='current',LEASE='writer';
let dbPromise,owner=null;
export async function checksum(text){return sha256Text(text)}
export function openDB(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(Error('本機儲存無法使用'));const r=indexedDB.open(NAME,1);r.onupgradeneeded=()=>{for(const n of ['save','archives','journal','legacy','leases'])if(!r.result.objectStoreNames.contains(n))r.result.createObjectStore(n)};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('請關閉另一個舊分頁後再開啟'))});return dbPromise}
async function get(store,key){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction(store,'readonly').objectStore(store).get(key);r.onsuccess=()=>resolve(r.result||null);r.onerror=()=>reject(r.error)})}
export async function decodeEnvelope(env){if(!env)return null;if(typeof env.stateJSON!=='string'||await checksum(env.stateJSON)!==env.checksum)throw Error('存檔校驗失敗，已停止覆寫');const state=JSON.parse(env.stateJSON),r=validate(state);if(!r.ok)throw Error('存檔不相容：'+r.errors.join('；'));return{...env,state}}
export async function readSave(){return decodeEnvelope(await get('save',KEY))}
export async function readRecovery(){return decodeEnvelope(await get('save','last-known-good'))}
export async function writeSave(state,expectedRevision,resolvedAt,{archive=false,operation='checkpoint'}={}){const v=validate(state);if(!v.ok)throw Error('拒絕儲存無效狀態：'+v.errors.join('；'));if(!owner)throw Error('此分頁没有寫入權限');if(!Number.isSafeInteger(expectedRevision)||expectedRevision<0||!Number.isFinite(resolvedAt)||resolvedAt<0)throw Error('存檔修訂或時間無效');const stateJSON=JSON.stringify(state),snapshot=JSON.parse(stateJSON),digest=await checksum(stateJSON),d=await openDB();return new Promise((resolve,reject)=>{const tx=d.transaction(['save','archives','journal','leases'],'readwrite'),save=tx.objectStore('save');let old,lease,reads=0,result,failed=false;function abort(message){failed=true;try{tx.abort()}catch{}reject(Error(message))}function commit(){if(++reads<2)return;if(lease?.owner!==owner)return abort('寫入租約已失效，請重新載入');if((old?.revision||0)!==expectedRevision)return abort('另一分頁已更新進度，已阻止覆寫');const revision=expectedRevision+1;result={schema:3,revision,resolvedAt,checksum:digest,stateJSON,contentVersion:snapshot.contentVersion};if(old){save.put(old,'last-known-good');if(archive)tx.objectStore('archives').put(old,'before-'+old.revision)}save.put(result,KEY);tx.objectStore('journal').put({revision,operation,previousChecksum:old?.checksum||null,checksum:digest,resolvedAt,simulationMs:snapshot.elapsedMs},revision%512);tx.objectStore('leases').put({...lease,expiresAt:Date.now()+30000},LEASE)}const r=save.get(KEY);r.onsuccess=()=>{old=r.result;commit()};r.onerror=()=>abort('讀取目前修訂失敗');const l=tx.objectStore('leases').get(LEASE);l.onsuccess=()=>{lease=l.result;commit()};l.onerror=()=>abort('讀取寫入租約失敗');tx.oncomplete=()=>resolve({...result,state:JSON.parse(stateJSON)});tx.onerror=()=>{if(!failed)reject(tx.error||Error('儲存失敗，原快照保留'))};tx.onabort=()=>{if(!failed)reject(tx.error||Error('儲存中斷，原快照保留'))}})}
async function lease(action){const d=await openDB(),token=owner;return new Promise((resolve,reject)=>{const tx=d.transaction('leases','readwrite'),store=tx.objectStore('leases'),r=store.get(LEASE);let ok=false;r.onsuccess=()=>{const previous=r.result,now=Date.now();if(action==='release'){if(previous?.owner===token)store.delete(LEASE);ok=true}else if(!previous||previous.expiresAt<now||previous.owner===token){store.put({owner:token,expiresAt:now+30000},LEASE);ok=true}};tx.oncomplete=()=>resolve(ok);tx.onerror=()=>reject(tx.error)})}
export async function acquireSession(){owner=randomSessionId();let releaseLock=null;if(navigator.locks?.request){const granted=await new Promise(resolve=>navigator.locks.request('ashen-covenant-play',{ifAvailable:true},async lock=>{if(!lock)return resolve(false);const holding=new Promise(r=>releaseLock=r);resolve(true);await holding}).catch(()=>resolve(false)));if(!granted){owner=null;return{owned:false,release(){}}}}const acquired=await lease('acquire');if(!acquired){releaseLock?.();owner=null;return{owned:false,release(){}}}const timer=setInterval(()=>lease('renew').then(ok=>{if(!ok){owner=null;clearInterval(timer)}}).catch(()=>{}),10000);return{owned:true,async release(){clearInterval(timer);await lease('release');owner=null;releaseLock?.()}}}
export async function listArchives(){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction('archives','readonly').objectStore('archives').getAll();r.onsuccess=()=>resolve(r.result.sort((a,b)=>b.revision-a.revision));r.onerror=()=>reject(r.error)})}
async function readV2(){return new Promise((resolve,reject)=>{let absent=false;const r=indexedDB.open('ashen-covenant-v2');r.onupgradeneeded=()=>{absent=true;r.transaction.abort()};r.onerror=()=>absent?resolve(null):reject(r.error);r.onsuccess=()=>{const d=r.result;if(!d.objectStoreNames.contains('save')){d.close();return resolve(null)}const tx=d.transaction(['save',...(d.objectStoreNames.contains('archives')?['archives']:[])],'readonly'),a=tx.objectStore('save').get('current');let current=null,archives=[];a.onsuccess=()=>current=a.result||null;if(d.objectStoreNames.contains('archives')){const b=tx.objectStore('archives').getAll();b.onsuccess=()=>archives=b.result}tx.oncomplete=()=>{d.close();resolve({current,archives})};tx.onerror=()=>{d.close();reject(tx.error)}}})}
export async function preserveLegacy(){const v1=localStorage.getItem('ashen-covenant-v1'),v2=await readV2(),d=await openDB();const records=[];if(v1)records.push({key:'v1-original',format:'v1-raw',raw:v1});if(v2?.current||v2?.archives.length)records.push({key:'v2-original-'+(v2.current?.revision||0),format:'v2-envelope',raw:JSON.stringify(v2)});await new Promise((resolve,reject)=>{const tx=d.transaction('legacy','readwrite'),store=tx.objectStore('legacy');for(const row of records){const r=store.get(row.key);r.onsuccess=()=>{if(!r.result)store.add({...row,preservedAt:Date.now()},row.key)}}tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return listLegacy()}
export async function listLegacy(){const d=await openDB();return new Promise((resolve,reject)=>{const r=d.transaction('legacy','readonly').objectStore('legacy').getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
export async function exportEnvelope(state,resolvedAt){const stateJSON=JSON.stringify(state);return{format:'ashen-covenant-v3',exportedAt:new Date().toISOString(),resolvedAt,checksum:await checksum(stateJSON),stateJSON}}
export async function parseImport(raw){const input=JSON.parse(raw);if(input.format!=='ashen-covenant-v3')return{legacy:true,format:input.format||input.version||input.schema,raw};if(typeof input.stateJSON!=='string'||await checksum(input.stateJSON)!==input.checksum)throw Error('備份校驗不符');if(!Number.isFinite(input.resolvedAt)||input.resolvedAt<0)throw Error('備份時間無效');const state=JSON.parse(input.stateJSON),v=validate(state);if(!v.ok)throw Error(v.errors.join('；'));return{state,exportedAt:input.exportedAt,resolvedAt:input.resolvedAt}}
